create table if not exists public.v26_scenarios (id uuid primary key default gen_random_uuid(),business_id uuid not null references public.businesses(id) on delete cascade,name text not null,horizon_days integer not null default 14 check(horizon_days between 1 and 90),actions jsonb not null default '[]'::jsonb,status text not null default 'draft' check(status in ('draft','active','archived')),created_by uuid references auth.users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now()); create table if not exists public.v26_simulation_runs (id uuid primary key default gen_random_uuid(),business_id uuid not null references public.businesses(id) on delete cascade,scenario_id uuid not null references public.v26_scenarios(id) on delete cascade,horizon_days integer not null,started_at timestamptz not null default now(),completed_at timestamptz,position_count integer not null default 0,breach_count integer not null default 0,stockout_count integer not null default 0,critical_count integer not null default 0,projected_exposure numeric(24,8) not null default 0,created_by uuid references auth.users(id)); create table if not exists public.v26_position_results (id uuid primary key default gen_random_uuid(),business_id uuid not null references public.businesses(id) on delete cascade,run_id uuid not null references public.v26_simulation_runs(id) on delete cascade,location_id uuid not null references public.locations(id) on delete restrict,ingredient_id uuid not null references public.ingredients(id) on delete restrict,unit text not null,baseline_stock numeric(24,8) not null,baseline_rop numeric(24,8) not null,baseline_daily_demand numeric(24,8) not null,projected_daily_demand numeric(24,8) not null,projected_lead_time_days numeric(24,8) not null,projected_safety_stock numeric(24,8) not null,projected_rop numeric(24,8) not null,projected_inbound numeric(24,8) not null default 0,projected_stock numeric(24,8) not null,projected_stockout_day integer,projected_rop_breach_day integer,risk_score numeric(8,4) not null default 0,risk_level text not null check(risk_level in ('low','medium','high','critical')),projected_cost_exposure numeric(24,8) not null default 0,action_effects jsonb not null default '{}'::jsonb,created_at timestamptz not null default now(),unique(run_id,location_id,ingredient_id,unit)); alter table public.v26_scenarios enable row level security; alter table public.v26_simulation_runs enable row level security; alter table public.v26_position_results enable row level security; drop policy if exists v26_scenarios_select on public.v26_scenarios; create policy v26_scenarios_select on public.v26_scenarios for select using(is_member(business_id)); drop policy if exists v26_runs_select on public.v26_simulation_runs; create policy v26_runs_select on public.v26_simulation_runs for select using(is_member(business_id)); drop policy if exists v26_results_select on public.v26_position_results; create policy v26_results_select on public.v26_position_results for select using(is_member(business_id)); revoke insert,update,delete on public.v26_scenarios,public.v26_simulation_runs,public.v26_position_results from authenticated; create or replace function public.create_v26_scenario(p_business_id uuid,p_name text,p_horizon_days integer,p_actions jsonb default '[]'::jsonb) returns uuid language plpgsql security definer set search_path=public as $$ declare sid uuid; begin if not has_role(p_business_id,ARRAY['owner','manager']::member_role[]) then raise exception 'Manager authorization required'; end if; if nullif(trim(p_name),'') is null then raise exception 'Scenario name required'; end if; if p_horizon_days not between 1 and 90 then raise exception 'Horizon must be between 1 and 90 days'; end if; if jsonb_typeof(coalesce(p_actions,'[]'::jsonb))<>'array' then raise exception 'Actions must be a JSON array'; end if; insert into public.v26_scenarios(business_id,name,horizon_days,actions,created_by) values(p_business_id,trim(p_name),p_horizon_days,coalesce(p_actions,'[]'::jsonb),auth.uid()) returning id into sid; return sid; end $$; grant execute on function public.create_v26_scenario(uuid,text,integer,jsonb) to authenticated; create or replace function public.run_v26_simulation(p_scenario_id uuid) returns jsonb language plpgsql security definer set search_path=public as $$ declare sc record; run_id uuid; rec record; demand_multiplier numeric(24,8); stock_delta numeric(24,8); lead_delta numeric(24,8); projected_demand numeric(24,8); projected_lead numeric(24,8); projected_ss numeric(24,8); projected_rop numeric(24,8); projected_stock numeric(24,8); stockout_day integer; breach_day integer; risk numeric(8,4); level text; v_position_count integer:=0; v_breach_count integer:=0; v_stockout_count integer:=0; v_critical_count integer:=0; total_exposure numeric(24,8):=0; exposure numeric(24,8); begin select * into sc from public.v26_scenarios where id=p_scenario_id for update; if sc.id is null then raise exception 'Scenario not found'; end if; if not has_role(sc.business_id,ARRAY['owner','manager']::member_role[]) then raise exception 'Manager authorization required'; end if; if sc.status='archived' then raise exception 'Archived scenario cannot run'; end if; perform pg_advisory_xact_lock(hashtextextended(sc.business_id::text,2600)); insert into public.v26_simulation_runs(business_id,scenario_id,horizon_days,created_by) values(sc.business_id,sc.id,sc.horizon_days,auth.uid()) returning id into run_id; for rec in select * from public.view_v20_location_reorder where business_id=sc.business_id loop select coalesce(exp(sum(ln(greatest(.01,(x->>'value')::numeric))) filter(where x->>'action_type'='demand_multiplier')),1),coalesce(sum((x->>'value')::numeric) filter(where x->>'action_type'='stock_delta'),0),coalesce(sum((x->>'value')::numeric) filter(where x->>'action_type'='lead_time_delta'),0) into demand_multiplier,stock_delta,lead_delta from jsonb_array_elements(sc.actions) x where coalesce(x->>'location_id','') in ('',rec.location_id::text) and coalesce(x->>'ingredient_id','') in ('',rec.ingredient_id::text); if rec.cold_start then continue; end if; projected_demand:=greatest(0,coalesce(rec.average_daily_demand,0)*demand_multiplier); projected_lead:=greatest(0,coalesce(rec.lead_time_days,0)+lead_delta); projected_ss:=greatest(0,(coalesce(rec.maximum_daily_demand,rec.average_daily_demand)*demand_multiplier-projected_demand)*projected_lead); projected_rop:=greatest(0,projected_demand*projected_lead+projected_ss); projected_stock:=greatest(0,coalesce(rec.current_stock,0)+stock_delta-(projected_demand*sc.horizon_days)); stockout_day:=case when projected_demand>0 and projected_stock=0 then greatest(1,ceil((coalesce(rec.current_stock,0)+stock_delta)/projected_demand))::integer else null end; breach_day:=case when projected_demand>0 and projected_stock<projected_rop then greatest(1,ceil((coalesce(rec.current_stock,0)+stock_delta-projected_rop)/projected_demand))::integer else null end; risk:=least(100,greatest(0,(case when stockout_day is not null then 65 else 0 end)+(case when breach_day is not null then 25 else 0 end))); level:=case when risk>=80 then 'critical' when risk>=55 then 'high' when risk>=25 then 'medium' else 'low' end; exposure:=greatest(0,projected_rop-projected_stock); insert into public.v26_position_results(business_id,run_id,location_id,ingredient_id,unit,baseline_stock,baseline_rop,baseline_daily_demand,projected_daily_demand,projected_lead_time_days,projected_safety_stock,projected_rop,projected_inbound,projected_stock,projected_stockout_day,projected_rop_breach_day,risk_score,risk_level,projected_cost_exposure,action_effects) values(sc.business_id,run_id,rec.location_id,rec.ingredient_id,rec.unit,coalesce(rec.current_stock,0),coalesce(rec.reorder_point,0),coalesce(rec.average_daily_demand,0),projected_demand,projected_lead,projected_ss,projected_rop,0,projected_stock,stockout_day,breach_day,risk,level,exposure,jsonb_build_object('demand_multiplier',demand_multiplier,'stock_delta',stock_delta,'lead_time_delta',lead_delta)); v_position_count:=v_position_count+1; if breach_day is not null then v_breach_count:=v_breach_count+1; end if; if stockout_day is not null then v_stockout_count:=v_stockout_count+1; end if; if level='critical' then v_critical_count:=v_critical_count+1; end if; total_exposure:=total_exposure+exposure; end loop; update public.v26_simulation_runs set completed_at=now(),position_count=v_position_count,breach_count=v_breach_count,stockout_count=v_stockout_count,critical_count=v_critical_count,projected_exposure=total_exposure where id=run_id; return jsonb_build_object('run_id',run_id,'position_count',v_position_count,'breach_count',v_breach_count,'stockout_count',v_stockout_count,'critical_count',v_critical_count,'projected_exposure',total_exposure); end $$; grant execute on function public.run_v26_simulation(uuid) to authenticated;